<?php
require_once __DIR__ . '/../includes/auth.php';
ini_set('display_errors', 0); ini_set('display_startup_errors', 0); error_reporting(0);
require __DIR__ . '/../includes/db.php';
$rental_id = (int)($_GET['rental_id'] ?? 0);
if ($rental_id <= 0) { header('Location: manage.php'); exit; }
$summaryStmt = $conn->prepare("SELECT r.id AS rental_id, r.start_date, r.end_date, r.total_cost, r.status AS rental_status, c.full_name AS customer_name, c.phone_number, c.email, ca.reg_no, m.name AS make_name, mo.name AS model_name, y.year AS car_year, IFNULL(SUM(p.amount), 0) AS total_paid, COUNT(p.id) AS payment_count FROM rentals r LEFT JOIN customers c ON r.customer_id = c.id LEFT JOIN cars ca ON r.cars_id = ca.id LEFT JOIN makes m ON ca.make_id = m.id LEFT JOIN models mo ON ca.model_id = mo.id LEFT JOIN car_years y ON ca.year_id = y.id LEFT JOIN payment p ON r.id = p.rental_id WHERE r.id = ? GROUP BY r.id, r.start_date, r.end_date, r.total_cost, r.status, c.full_name, c.phone_number, c.email, ca.reg_no, m.name, mo.name, y.year LIMIT 1");
$summaryStmt->bind_param('i', $rental_id); $summaryStmt->execute(); $summary = $summaryStmt->get_result()->fetch_assoc(); $summaryStmt->close();
if (!$summary) { header('Location: manage.php'); exit; }
$paymentsStmt = $conn->prepare("SELECT id, payment_date, amount, payment_method, payment_note FROM payment WHERE rental_id = ? ORDER BY payment_date ASC, id ASC");
$paymentsStmt->bind_param('i', $rental_id); $paymentsStmt->execute(); $payments = $paymentsStmt->get_result();
$carName = trim(($summary['make_name'] ?? '') . ' ' . ($summary['model_name'] ?? '') . ' ' . ($summary['car_year'] ?? '')); if ($carName === '') $carName = $summary['reg_no'] ?? 'N/A';
$bill = rental_bill_summary((float)$summary['total_cost'], (float)$summary['total_paid'], $summary['end_date']);
?>
<!DOCTYPE html><html lang="en"><head><meta charset="UTF-8"><meta name="viewport" content="width=device-width, initial-scale=1.0"><title>Payment History</title></head><body>
<?php include __DIR__ . '/../includes/header.php'; include __DIR__ . '/../includes/leftsidebar.php'; ?>
<div class="content-page"><h2>Payment History</h2>
<div class="payment-history-summary"><div><h3><?= h($summary['customer_name']); ?></h3><p><?= h($summary['phone_number']); ?> <?= $summary['email'] ? ' | ' . h($summary['email']) : ''; ?></p></div><div><strong>Rental #<?= h($summary['rental_id']); ?></strong><p><?= h($carName); ?> | Reg: <?= h($summary['reg_no']); ?></p></div><div><strong><?= h($summary['start_date']); ?> to <?= h($summary['end_date']); ?></strong><p>Status: <?= h($summary['rental_status']); ?></p></div></div>
<div class="payment-total-grid"><div class="card-box"><p>Rental Cost</p><h2><?= number_format((float)$summary['total_cost'], 2); ?> TRY</h2></div><div class="card-box"><p>Late Interest</p><h2><?= number_format((float)$bill['late_interest'], 2); ?> TRY</h2><p><?= h($bill['late_days']); ?> late day(s)</p></div><div class="card-box"><p>Total Due</p><h2><?= number_format((float)$bill['grand_total'], 2); ?> TRY</h2></div><div class="card-box"><p>Total Paid</p><h2><?= number_format((float)$summary['total_paid'], 2); ?> TRY</h2></div><div class="card-box"><p>Remaining</p><h2><?= number_format((float)$bill['remaining'], 2); ?> TRY</h2></div><div class="card-box"><p>Payment Status</p><h2><?= h($bill['status']); ?></h2></div></div>
<div style="margin:14px 0;"><a href="manage.php" class="btn btn-primary">Back to Payments</a></div>
<div class="table-responsive"><table class="table" border="1" cellpadding="10"><thead><tr><th>#</th><th>Payment Date</th><th>Method</th><th>Note</th><th>Amount Paid</th><th>Running Total</th><th>Balance After Payment</th></tr></thead><tbody>
<?php if ($payments && $payments->num_rows > 0): ?><?php $i=1; $running=0; while ($payment=$payments->fetch_assoc()): $running+=(float)$payment['amount']; $balanceAfter=max((float)$bill['grand_total']-$running,0); ?><tr><td><?= $i++; ?></td><td><?= h($payment['payment_date']); ?></td><td><?= h($payment['payment_method'] ?? ""); ?></td><td><?= h($payment['payment_note'] ?? ""); ?></td><td><?= number_format((float)$payment['amount'],2); ?> TRY</td><td><?= number_format($running,2); ?> TRY</td><td><?= number_format($balanceAfter,2); ?> TRY</td></tr><?php endwhile; ?><?php else: ?><tr><td colspan="7">No payment has been recorded for this rental yet.</td></tr><?php endif; ?></tbody></table></div></div></body></html>
